"""Bulk READ benchmark fixture, not evidence of Service command correctness. No delete/reset."""
from perf_common import *
assert db('SELECT DATABASE()')=='leaseguard_perf'
assert db("SELECT COUNT(*) FROM user WHERE id>=100 AND id<>101 AND id<>102 AND id<>103")== '0','Seed requires a new perf dataset'
db("INSERT INTO user(id,username,password,nickname,role) VALUES (101,'g5_admin','!G5_SYNTHETIC_NON_LOGIN!','SYNTHETIC admin',1),(102,'g5_tech_a','!G5_SYNTHETIC_NON_LOGIN!','SYNTHETIC tech A',2),(103,'g5_tech_b','!G5_SYNTHETIC_NON_LOGIN!','SYNTHETIC tech B',2)")
def numbers(start,end):return f"WITH RECURSIVE n(v) AS(SELECT {start} UNION ALL SELECT v+1 FROM n WHERE v<{end}) "
db("SET SESSION cte_max_recursion_depth=110000;INSERT INTO user(id,username,password,nickname,role) "+numbers(1,10000)+"SELECT 1000+v,CONCAT('g5_user_',v),'!G5_SYNTHETIC_NON_LOGIN!',CONCAT('SYNTHETIC user ',v),0 FROM n")
db("SET SESSION cte_max_recursion_depth=2000;INSERT INTO drone(id,model,brand,type,price_per_day,stock,status,on_shelf) "+numbers(1,1000)+"SELECT v,CONCAT('SYNTHETIC G5 MODEL ',v),'LeaseGuard synthetic','巡检',12.50,2000,1,1 FROM n")
db("INSERT INTO user_qualification(user_id,certificate_no,valid_start_date,valid_end_date,audit_status) VALUES(1001,'SYNTHETIC-G5-NOT-A-CERTIFICATE','2020-01-01','2099-12-31',1)")
stages=[];start=1
for target in [10000,50000,100000]:
 began=time.monotonic();span=f' BETWEEN {start} AND {target}'
 db("SET SESSION cte_max_recursion_depth=110000;INSERT INTO rental_order(id,order_no,user_id,drone_id,rental_start_time,rental_end_time,rental_days,unit_price,total_amount,order_status,inventory_held,created_time) "+numbers(start,target)+"SELECT v,CONCAT('SYNTHETIC_G5_',LPAD(v,8,'0')),IF(v<=10000,1001,1002+MOD(v,9999)),1+MOD(v,1000),'2025-01-01','2025-01-02',2,12.50,25,MOD(v,7),IF(MOD(v,7)<4,1,0),DATE_ADD('2025-01-01',INTERVAL MOD(v,365) DAY) FROM n")
 db("INSERT INTO command_dedup(id,actor_id,operation,request_key,request_hash,resource_id,response_json) SELECT id,user_id,'SYNTHETIC_SEED',CONCAT('synthetic-seed-',id),REPEAT('0',64),id,JSON_OBJECT('synthetic',true) FROM rental_order WHERE id"+span)
 db("INSERT INTO business_event(aggregate_type,aggregate_id,command_id,seq_no,event_type,from_status,to_status,actor_id) SELECT 'ORDER',id,id,1,'SYNTHETIC_SNAPSHOT',NULL,order_status,user_id FROM rental_order WHERE id"+span)
 # Stage starts at previous stock; each unit allocation/release is chained in log-ID order.
 db("INSERT INTO drone_stock_log(id,drone_id,change_type,change_amount,before_stock,after_stock,related_order_id,remark,operator_id,command_id,event_type,inventory_effect) SELECT x.log_id,x.drone_id,IF(x.delta=-1,2,3),x.delta,d.stock+SUM(x.delta) OVER(PARTITION BY x.drone_id ORDER BY x.log_id)-x.delta,d.stock+SUM(x.delta) OVER(PARTITION BY x.drone_id ORDER BY x.log_id),x.oid,'SYNTHETIC bulk read fixture',ro.user_id,x.oid,IF(x.delta=-1,'ALLOCATE','RELEASE'),IF(x.delta=-1,'ALLOCATE','RELEASE') FROM(SELECT id*2 AS log_id,drone_id,id AS oid,-1 AS delta FROM rental_order WHERE id"+span+" UNION ALL SELECT id*2+1,drone_id,id,1 FROM rental_order WHERE inventory_held=0 AND id"+span+") x JOIN drone d ON d.id=x.drone_id JOIN rental_order ro ON ro.id=x.oid")
 db("INSERT INTO business_event(aggregate_type,aggregate_id,command_id,seq_no,event_type,from_status,to_status,actor_id) SELECT 'DRONE',l.drone_id,l.command_id,IF(l.inventory_effect='ALLOCATE',2,3),l.inventory_effect,l.before_stock,l.after_stock,c.actor_id FROM drone_stock_log l JOIN command_dedup c ON c.id=l.command_id WHERE l.related_order_id"+span)
 db("UPDATE drone d JOIN(SELECT drone_id,COUNT(*) AS held FROM rental_order WHERE inventory_held=1 GROUP BY drone_id)x ON x.drone_id=d.id SET d.stock=2000-x.held")
 db("INSERT INTO fault_report(id,report_no,user_id,drone_id,order_id,fault_type,fault_description,audit_status) SELECT id,CONCAT('SYNTHETIC_FAULT_',id),user_id,drone_id,id,'SYNTHETIC','SYNTHETIC G5 read fixture',1 FROM rental_order WHERE order_status=3 AND MOD(id,5)=0 AND id"+span)
 db("INSERT INTO maintenance_ticket(id,ticket_no,fault_report_id,drone_id,user_id,maintenance_description,status,assignee_id,assignee_name,assigned_at,accepted_by,accepted_at) SELECT id,CONCAT('SYNTHETIC_TICKET_',id),id,drone_id,user_id,'SYNTHETIC read fixture',CASE MOD(id,4) WHEN 2 THEN 4 WHEN 3 THEN 2 ELSE MOD(id,4) END,IF(MOD(id,2)=0,102,103),IF(MOD(id,2)=0,'g5_tech_a','g5_tech_b'),'2025-01-01',IF(MOD(id,4)=3,101,NULL),IF(MOD(id,4)=3,'2025-01-03',NULL) FROM fault_report WHERE id"+span)
 db("UPDATE drone d SET status=IF(EXISTS(SELECT 1 FROM maintenance_ticket t WHERE t.drone_id=d.id AND t.status IN(0,1,4)),2,IF(d.stock>0,1,0))")
 db("INSERT INTO return_request(order_id,user_id,status,submitted_at,reviewed_at,reviewer_id) SELECT id,user_id,IF(order_status=4,1,0),'2025-01-02',IF(order_status=4,'2025-01-03',NULL),IF(order_status=4,101,NULL) FROM rental_order WHERE (order_status=4 OR(order_status=3 AND MOD(id,2)=0)) AND id"+span)
 db("INSERT INTO job_task(business_key,order_id,type,status,due_at,available_at,attempts,max_attempts,result,last_error,created_command_id,created_at,updated_at,completed_at) SELECT CONCAT('timeout-order-',id),id,'ORDER_TIMEOUT',IF(order_status=0,'FAILED','DONE'),'2025-01-01','2025-01-01',IF(order_status=0,5,1),5,IF(order_status=0,NULL,IF(order_status=5,'CANCELLED','NO_ACTION')),IF(order_status=0,'SYNTHETIC_IMPORTED_FAILURE',NULL),id,'2025-01-01','2025-01-01','2025-01-01' FROM rental_order WHERE MOD(id,10)=0 AND id"+span)
 counts={table:int(db('SELECT COUNT(*) FROM '+table)) for table in ['user','rental_order','drone','fault_report','maintenance_ticket','return_request','drone_stock_log','command_dedup','business_event','job_task']}
 assert counts['rental_order']==target
 assert db('SELECT COUNT(*) FROM drone d WHERE d.stock<>(2000-(SELECT COUNT(*) FROM rental_order o WHERE o.drone_id=d.id AND o.inventory_held=1))')=='0'
 stages.append({'target':target,'actual_counts':counts,'seconds':round(time.monotonic()-began,3),'fixture_type':'SYNTHETIC_BULK_READ_NOT_SERVICE_PROOF','stock_balance':True});(D/'dataset.json').write_text(json.dumps(stages,indent=2));print('Seed verified',target,'orders',flush=True);start=target+1
db('ANALYZE TABLE rental_order,maintenance_ticket,business_event,job_task,drone')

# Historical synthetic accounts/models predate the rental date range.
db("UPDATE user SET created_time='2024-12-01',updated_time=updated_time WHERE username LIKE 'g5_user_%' OR id IN(101,102,103);UPDATE drone SET created_time='2024-12-01',updated_time=updated_time WHERE id<=1000")
